CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,username TEXT UNIQUE,hash TEXT,salt TEXT,role TEXT);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER,expires BIGINT);
CREATE TABLE IF NOT EXISTS customers(id SERIAL PRIMARY KEY,name TEXT NOT NULL,phone TEXT DEFAULT '',notes TEXT DEFAULT '',deleted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS products(id SERIAL PRIMARY KEY,name TEXT NOT NULL,price BIGINT NOT NULL,cost BIGINT NOT NULL,stock INTEGER NOT NULL,minimum INTEGER DEFAULT 5,service INTEGER DEFAULT 0,active INTEGER DEFAULT 1,price_ready INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS invoices(id SERIAL PRIMARY KEY,customer_id INTEGER REFERENCES customers(id),created TEXT NOT NULL,total BIGINT NOT NULL,paid BIGINT NOT NULL,discount BIGINT DEFAULT 0,status TEXT DEFAULT 'active',reason TEXT,actor TEXT,deleted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS items(id SERIAL PRIMARY KEY,invoice_id INTEGER REFERENCES invoices(id),product_id INTEGER REFERENCES products(id),name TEXT,quantity INTEGER,price BIGINT,cost BIGINT,service INTEGER);
CREATE TABLE IF NOT EXISTS payments(id SERIAL PRIMARY KEY,customer_id INTEGER REFERENCES customers(id),invoice_id INTEGER REFERENCES invoices(id),amount BIGINT NOT NULL,method TEXT,created TEXT,actor TEXT,status TEXT DEFAULT 'active',deleted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS expenses(id SERIAL PRIMARY KEY,title TEXT,amount BIGINT,created TEXT,actor TEXT);
CREATE TABLE IF NOT EXISTS movements(id SERIAL PRIMARY KEY,product_id INTEGER REFERENCES products(id),quantity INTEGER,cost BIGINT,reason TEXT,created TEXT,actor TEXT);
CREATE TABLE IF NOT EXISTS audit(id SERIAL PRIMARY KEY,action TEXT,actor TEXT,created TEXT);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT);
CREATE TABLE IF NOT EXISTS requests(key TEXT PRIMARY KEY,result TEXT);
CREATE TABLE IF NOT EXISTS site_documents(id TEXT PRIMARY KEY,published TEXT NOT NULL,draft TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS site_versions(id TEXT PRIMARY KEY,content TEXT NOT NULL,created TEXT NOT NULL,actor TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS site_media(id TEXT PRIMARY KEY,mime TEXT NOT NULL,content TEXT NOT NULL);
